few_shot_examples.query:
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?agent
WHERE {
  ?publication coresr-ont:submittedBy ?agent .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?contact .
    ?contact rdf:type/rdfs:subClassOf* coresr-ont:EmailAddress .
  }
}
